import{_ as t}from"./chunks/image.1TJKpa6R.js";import{_ as a,o as r,c as n,a2 as i}from"./chunks/framework.CdjpmwdR.js";const _=JSON.parse('{"title":"Tunnel、VPN、VPC：概念边界与关系","description":"从网络连接视角拆解 Tunnel、VPN、VPC 三个概念，解释它们在跨网互通、安全传输和虚拟网络抽象方面的分工与协作。","frontmatter":{"category":"node","date":"2023-04-01","title":"Tunnel、VPN、VPC：概念边界与关系","description":"从网络连接视角拆解 Tunnel、VPN、VPC 三个概念，解释它们在跨网互通、安全传输和虚拟网络抽象方面的分工与协作。","tags":["node","K8s"],"image":"/blogs/assets/202304-tunnel-vpn-vpc/image.png"},"headers":[],"relativePath":"blogs/2023/202304-tunnel-vpn-vpc.md","filePath":"blogs/2023/202304-tunnel-vpn-vpc.md"}'),l={name:"blogs/2023/202304-tunnel-vpn-vpc.md"};function s(o,e,c,h,p,u){return r(),n("div",null,[...e[0]||(e[0]=[i('<p>这篇是我在梳理 VPN 相关技术时做的概念澄清笔记。</p><blockquote><p><a href="./../2022/202205-router-proxy-gtw">路由 vs 代理 vs 网关</a> 的续集</p></blockquote><h2 id="隧道-tunnel-连接-2-个不可达网络" tabindex="-1">隧道 Tunnel - 连接 2 个不可达网络 <a class="header-anchor" href="#隧道-tunnel-连接-2-个不可达网络" aria-label="Permalink to &quot;隧道 Tunnel - 连接 2 个不可达网络&quot;">​</a></h2><p><img src="https://s2.loli.net/2023/04/17/y5EnxTrbtIAN7z9.png" alt="tunnel"></p><p>路由和代理通常以转发为主，而隧道更强调“封装后再传输”。它常用于跨公网打通两个原本不可达的网络，或连接不同协议域。</p><p>因此隧道往往会对原始数据帧进行：</p><ul><li>包装、改写报文头</li><li>加密</li><li>添加额外信息（日志、追踪）</li><li>...</li></ul><p>网络的每一层都是对报文的包装，所以隧道可以工作在任何一层，只需编写对应的隧道程序，编码和解码该层的报文。</p><h2 id="虚拟私有网络-vpn" tabindex="-1">虚拟私有网络 VPN <a class="header-anchor" href="#虚拟私有网络-vpn" aria-label="Permalink to &quot;虚拟私有网络 VPN&quot;">​</a></h2><p><img src="https://s2.loli.net/2023/04/17/KMUOH1bTycPYtJv.png" alt="vpn"></p><p>VPN 有明确的 Server/Client 2 端，Client 必须与 Server 连接才能正常工作</p><ul><li>此时的 Server 就是一个网关设备，用于连接不同网络的 client 设备</li><li>此时 Server 和 Client 的连接也都是基于隧道技术，以保证跨网络传输时的数据安全</li></ul><h2 id="虚拟设备-tun-tap" tabindex="-1">虚拟设备 TUN/TAP <a class="header-anchor" href="#虚拟设备-tun-tap" aria-label="Permalink to &quot;虚拟设备 TUN/TAP&quot;">​</a></h2><p>TUN/TAP 是 Linux 内核的虚拟设备，使单一节点具有多个虚拟地址（IP/Mac），也可以配合 VPN 使用。</p><h2 id="underlay-vs-overlay" tabindex="-1">Underlay vs Overlay <a class="header-anchor" href="#underlay-vs-overlay" aria-label="Permalink to &quot;Underlay vs Overlay&quot;">​</a></h2><p>得益于隧道和虚拟设备，逻辑上的网络架构和物理层的网络架构可以呈现出完全不同的表现。</p><ul><li>相隔万里的 2 台主机可以工作在同一个局域网，使用同一个网段</li><li>一台主机上的 2 个应用处于不同的虚拟网络，相互隔离</li></ul><h2 id="虚拟私有云-vpc-vnet" tabindex="-1">虚拟私有云 VPC / Vnet <a class="header-anchor" href="#虚拟私有云-vpc-vnet" aria-label="Permalink to &quot;虚拟私有云 VPC / Vnet&quot;">​</a></h2><p>随着虚拟设备的增多，VPN 需要处理多节点、组播、广播以及同一 host 下的 VM 互通，因此分支出了虚拟局域网相关技术，用于构建数据中心的大规模网络。</p><h2 id="虚拟网络-vs-容器网络" tabindex="-1">虚拟网络 vs 容器网络 <a class="header-anchor" href="#虚拟网络-vs-容器网络" aria-label="Permalink to &quot;虚拟网络 vs 容器网络&quot;">​</a></h2><p>这两者其实很像...</p><h2 id="附录-全景图" tabindex="-1">附录：全景图 <a class="header-anchor" href="#附录-全景图" aria-label="Permalink to &quot;附录：全景图&quot;">​</a></h2><p><img src="'+t+'" alt="landscape"></p><h3 id="documents" tabindex="-1">Documents <a class="header-anchor" href="#documents" aria-label="Permalink to &quot;Documents&quot;">​</a></h3><ul><li><a href="https://support.huawei.com/enterprise/zh/doc/EDOC1100164807" target="_blank" rel="noreferrer">https://support.huawei.com/enterprise/zh/doc/EDOC1100164807</a></li><li><a href="https://itnext.io/kubernetes-is-hard-why-eks-makes-it-easier-for-network-and-security-architects-ea6d8b2ca965" target="_blank" rel="noreferrer">https://itnext.io/kubernetes-is-hard-why-eks-makes-it-easier-for-network-and-security-architects-ea6d8b2ca965</a></li><li><a href="https://www.pinterest.com/pin/coreosflannel--22940279328297785/" target="_blank" rel="noreferrer">https://www.pinterest.com/pin/coreosflannel--22940279328297785/</a></li><li><a href="https://access.redhat.com/documentation/en-us/red_hat_virtualization/4.4/html/technical_reference/cluster_networking" target="_blank" rel="noreferrer">https://access.redhat.com/documentation/en-us/red_hat_virtualization/4.4/html/technical_reference/cluster_networking</a></li><li><a href="https://www.rebeladmin.com/2018/01/azure-accelerated-networking/" target="_blank" rel="noreferrer">https://www.rebeladmin.com/2018/01/azure-accelerated-networking/</a></li><li><a href="https://dzone.com/articles/step-by-step-guide-establishing-container-networki" target="_blank" rel="noreferrer">https://dzone.com/articles/step-by-step-guide-establishing-container-networki</a></li><li><a href="https://access.redhat.com/documentation/en-us/red_hat_enterprise_linux/6/html/virtualization_administration_guide/sect-attch-nic-physdev" target="_blank" rel="noreferrer">https://access.redhat.com/documentation/en-us/red_hat_enterprise_linux/6/html/virtualization_administration_guide/sect-attch-nic-physdev</a></li><li><a href="https://zh.wikipedia.org/zh-cn/%E9%9A%A7%E9%81%93%E5%8D%8F%E8%AE%AE" target="_blank" rel="noreferrer">https://zh.wikipedia.org/zh-cn/隧道协议</a></li></ul>',25)])])}const b=a(l,[["render",s]]);export{_ as __pageData,b as default};
